-- Average price
SELECT AVG(price) FROM products;

-- Highest and lowest
SELECT MAX(price), MIN(price) FROM products;

-- Products priced above average
SELECT name, price
FROM products
WHERE price > (
    SELECT AVG(price) FROM products
);

-- Users who placed an order
SELECT * FROM users
WHERE id IN (
    SELECT DISTINCT user_id FROM orders
);

