-- Auto-incrementing primary key (most common)
CREATE TABLE users (
    id SERIAL PRIMARY KEY,  -- Auto-increments
    email TEXT UNIQUE,      -- Business identifier
    name TEXT
);

-- UUID primary key
CREATE TABLE orders (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id INTEGER REFERENCES users(id)
);

